"use client";
import React from "react";
import VendorDashbordLayout from "./VendorDashbordLayout";
import { useSelector } from "react-redux";

function VenderDashboard() {
  const user = useSelector((state: any) => state.user.userData);

  // ✅ Jab tak admin approve na kare
  if (!user || user.verificationStatus !== "approved") {
    return (
      <div className="w-full min-h-screen flex items-center justify-center bg-gradient-to-br from-gray-900 via-black to-gray-900 text-white px-4">
        
        <div className="bg-white/10 backdrop-blur-md p-12 rounded-2xl shadow-2xl border border-white/30 
                        max-w-2xl w-full text-center">
          
          <h2 className="text-4xl font-bold mb-6 text-blue-400">
            Verification Pending
          </h2>

          <p className="text-gray-200 text-lg leading-relaxed">
            You can access vendor details only after
            <span className=" font-semibold"> admin verification</span>.
            <br />
            This process usually takes
            <span className="text-blue-400 font-semibold"> 2–3 hours</span>.
          </p>

          <div className="mt-6 text-base text-gray-300">
            Current Status:{" "}
            <span className="text-blue-400 font-semibold uppercase tracking-wide">
              {user?.verificationStatus}
            </span>
          </div>

          <div className="mt-10 text-sm text-gray-400">
            Please wait while our team verifies your business details.
          </div>
        </div>
      </div>
    );
  }

  // ✅ Only approved vendors can access dashboard
  return (
    <div className="w-full min-h-screen pt-16">
      <VendorDashbordLayout />
    </div>
  );
}

export default VenderDashboard;
